// Verificar título
cy.contains("Catálogo de activos").should("be.visible");
// Verificar descripción
cy.contains("Visualiza los activos con su imagen, tipo y estado").should("be.visible");
// Verificar barra de búsqueda
cy.get('input[placeholder="Buscar activo por nombre"]').should("be.visible");
// Verificar botón nuevo activo
cy.contains("Nuevo activo").should("be.visible");
// Verificar filtros
cy.contains("Todos").should("be.visible");
cy.contains("Celular").should("be.visible");
cy.contains("Tablet").should("be.visible");
cy.contains("Periféricos").should("be.visible");
cy.contains("Pantalla").should("be.visible");

cy.get('input[placeholder="Buscar activo por nombre"]').should("be.visible").type("iPhone");
// Verificar que el campo conserva el texto
cy.get('input[placeholder="Buscar activo por nombre"]').should("have.value", "iPhone");

// Seleccionar filtro Celular
cy.contains("Celular").click();
// Verificar que el botón queda activo
cy.contains("Celular").should("have.class", "active");

// Buscar el primer botón "Ver detalles"
cy.contains("Ver detalles").first().should("be.visible").click();
// Verificar que aparece el modal
cy.get(".modal-overlay").should("be.visible");
// Verificar información del modal
cy.get(".modal-titulo").should("be.visible");
cy.contains("Tipo").should("be.visible");
cy.contains("N° de serie").should("be.visible");
cy.contains("Responsable").should("be.visible");
cy.contains("Descripción").should("be.visible");

// Abrir detalles
cy.contains("Ver detalles").first().click();
// Verificar modal
cy.get(".modal-overlay").should("be.visible");
// Cerrar modal
cy.get(".modal-close").click();
// Verificar que desapareció
cy.get(".modal-overlay").should("not.exist");

// Abrir responsable del primer activo
cy.contains("Responsable").first().click();
// Verificar modal
cy.get(".modal-overlay").should("be.visible");
// Verificar título
cy.contains("Asignar responsable").should("be.visible");
// Verificar información del activo
cy.contains("Activo:").should("be.visible");
// Verificar responsable actual
cy.contains("Responsable actual:").should("be.visible");

// Abrir modal
cy.contains("Responsable").first().click();
cy.get(".modal-overlay").should("be.visible");
// Cerrar
cy.get(".modal-close").click();
// Verificar cierre
cy.get(".modal-overlay").should("not.exist");
